// Array keywords for all supported drafts.
//
// Behaviors verified against the reference executable (jsonschema 4.23.0):
// - draft4 `items` is `items_draft3_draft4`: object form descends into every
//   element; anything else (array form) is zip()'d with the instance, so a
//   boolean `items` crashes the whole program. We mimic the crash by throwing.
// - draft6/7/2019 `items`: array form -> per-index zip; otherwise every
//   element descends against `items` (boolean `items` then works, one error
//   per element for `false`).
// - draft2020 `items`: array form crashes (modern implementation descends
//   with the raw list); boolean false yields a single error when elements
//   exist past `prefixItems`; otherwise elements at indexes >= prefix descend.
// - `prefixItems` is only a 2020 keyword (engine excludes it elsewhere).
// - `additionalItems` matters only when `items` is an array; that combination
//   crashes draft 2020 in the reference program, so its exact error count is
//   unobservable there. We follow the shared contract: `false` -> one error
//   per extra element.
// - `contains`: drafts 6/7 yield one error when nothing matches and ignore
//   minContains/maxContains; drafts 2019/2020 honor them (defaults 1 and
//   len(instance)) and yield at most one error.
// - `uniqueItems` uses jsonschema's `uniq` semantics: recursively, booleans
//   are only equal to the same boolean (1 != true), numbers compare by value
//   (1 == 1.0), arrays element-wise, objects key-wise (order-insensitive).

import { makeError } from "../errors.mjs";

function isPlainObject(v) {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

// Equality used by uniqueItems (jsonschema's uniq with recursive unbool).
function uniqEqual(a, b) {
  if (typeof a === "boolean" || typeof b === "boolean") return a === b;
  if (typeof a === "number" && typeof b === "number") return a === b;
  if (typeof a === "string" || typeof b === "string") return a === b;
  if (a === null || b === null) return a === b;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((x, i) => uniqEqual(x, b[i]));
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    return (
      ka.length === kb.length &&
      ka.every(
        (k) => Object.prototype.hasOwnProperty.call(b, k) && uniqEqual(a[k], b[k]),
      )
    );
  }
  return false;
}

function items(ctx, value, instance, schema) {
  if (!Array.isArray(instance)) return [];

  if (ctx.draft === 2020) {
    // Modern items: array form is not supported and crashes the reference
    // implementation (it descends with the raw list as the subschema).
    if (Array.isArray(value)) {
      throw new TypeError("array-form 'items' is not supported in draft 2020-12");
    }
    const prefixItems = schema.prefixItems;
    const prefix = Array.isArray(prefixItems) ? prefixItems.length : 0;
    if (value === false) {
      return instance.length > prefix ? [makeError()] : [];
    }
    const errors = [];
    for (let i = prefix; i < instance.length; i++) {
      errors.push(...ctx.descend(instance[i], value, [i], []));
    }
    return errors;
  }

  if (ctx.draft === 4) {
    // items_draft3_draft4: object form descends everywhere, anything else is
    // iterated with zip() -- so booleans crash with a TypeError in Python.
    if (isPlainObject(value)) {
      const errors = [];
      for (let i = 0; i < instance.length; i++) {
        errors.push(...ctx.descend(instance[i], value, [i], []));
      }
      return errors;
    }
    if (!Array.isArray(value)) {
      throw new TypeError("'bool' object is not iterable");
    }
    // fall through to the shared array form below
  } else if (!Array.isArray(value)) {
    // drafts 6/7/2019: non-array items applies to every element
    // (boolean subschemas are handled by the engine via descend).
    const errors = [];
    for (let i = 0; i < instance.length; i++) {
      errors.push(...ctx.descend(instance[i], value, [i], []));
    }
    return errors;
  }

  // Array form (drafts 4-2019): zip, i.e. stop at the shorter of the two.
  const errors = [];
  const n = Math.min(value.length, instance.length);
  for (let i = 0; i < n; i++) {
    errors.push(...ctx.descend(instance[i], value[i], [i], [i]));
  }
  return errors;
}

function additionalItems(ctx, value, instance, schema) {
  if (!Array.isArray(instance)) return [];
  const itemsValue = Object.prototype.hasOwnProperty.call(schema, "items")
    ? schema.items
    : {};
  if (isPlainObject(itemsValue)) return [];
  if (!Array.isArray(itemsValue)) {
    // boolean items: Python crashes on len(bool) here (the items keyword
    // itself crashes first in practice).
    throw new TypeError("object of type 'bool' has no len()");
  }
  const start = itemsValue.length;
  if (instance.length <= start) return [];
  if (value === true) return [];
  if (isPlainObject(value)) {
    const errors = [];
    for (let i = start; i < instance.length; i++) {
      errors.push(...ctx.descend(instance[i], value, [i], []));
    }
    return errors;
  }
  // value === false (or any other falsy): one error per extra element.
  const errors = [];
  for (let i = start; i < instance.length; i++) {
    errors.push(makeError());
  }
  return errors;
}

function prefixItems(ctx, value, instance, schema) {
  if (!Array.isArray(instance)) return [];
  if (!Array.isArray(value)) {
    throw new TypeError("object is not iterable");
  }
  const errors = [];
  const n = Math.min(value.length, instance.length);
  for (let i = 0; i < n; i++) {
    errors.push(...ctx.descend(instance[i], value[i], [i], [i]));
  }
  return errors;
}

function minItems(ctx, value, instance, schema) {
  if (!Array.isArray(instance)) return [];
  return instance.length < value ? [makeError()] : [];
}

function maxItems(ctx, value, instance, schema) {
  if (!Array.isArray(instance)) return [];
  return instance.length > value ? [makeError()] : [];
}

function uniqueItems(ctx, value, instance, schema) {
  if (!value || !Array.isArray(instance)) return [];
  for (let i = 0; i < instance.length; i++) {
    for (let j = i + 1; j < instance.length; j++) {
      if (uniqEqual(instance[i], instance[j])) {
        return [makeError()];
      }
    }
  }
  return [];
}

function contains(ctx, value, instance, schema) {
  if (!Array.isArray(instance)) return [];

  if (ctx.draft === 6 || ctx.draft === 7) {
    // minContains/maxContains are ignored before draft 2019.
    const any = instance.some((element) => ctx.isValid(element, value));
    return any ? [] : [makeError()];
  }

  // drafts 2019/2020
  const minContains = schema.minContains ?? 1;
  const maxContains = schema.maxContains ?? instance.length;
  let matches = 0;
  for (const element of instance) {
    if (ctx.isValid(element, value)) {
      matches += 1;
      if (matches > maxContains) {
        return [makeError()];
      }
    }
  }
  if (matches < minContains) {
    return [makeError()];
  }
  return [];
}

// minContains/maxContains are modifiers read by `contains` from the schema;
// they are not standalone keywords in jsonschema.
function minContains(ctx, value, instance, schema) {
  return [];
}

function maxContains(ctx, value, instance, schema) {
  return [];
}

export const keywords = {
  items,
  additionalItems,
  prefixItems,
  minItems,
  maxItems,
  uniqueItems,
  contains,
  minContains,
  maxContains,
};

